/*
 * ESP32 Web Server — serve an HTML dashboard and control the LED.
 * The simulator generates a fake HTTP request to each route every ~1.5s,
 * so watch the Serial Monitor to see requests and responses, and the LED
 * on D13 toggling as /on and /off are requested.
 */

#include <WiFi.h>
#include <WebServer.h>

const int ledPin  = 13;
const int sensorPin = 36;   // GPIO36 (VP) — potentiometer wiper
WebServer server(80);

int tempC = 25;

String buildPage() { 
  String html = ""; 
  html += "<!DOCTYPE html><html><head><title>ArduSim Web</title>";

  // Optional: CSS to make the links look like actual buttons
  html += "<style>";
  html += ".btn { display: inline-block; padding: 10px 20px; font-size: 16px; color: white; text-decoration: none; border-radius: 5px; margin: 5px; }";
  html += ".btn-on { background-color: #4CAF50; }";  // Green
  html += ".btn-off { background-color: #f44336; }"; // Red
  html += "</style>";

  html += "</head><body>"; 
  html += "<h1>ESP32 Web Server</h1>"; 
  html += "<p>Temperature: <b>" + String(tempC) + " &deg;C</b></p>"; 

  // Buttons
  html += "<p><a href=\"/on\" class=\"btn btn-on\">Turn LED ON</a></p>"; 
  html += "<p><a href=\"/off\" class=\"btn btn-off\">Turn LED OFF</a></p>"; 

  html += "</body></html>"; 
  return html; 
}


void handleRoot() {
  server.send(200, "text/html", buildPage());
}

void handleOn() {
  digitalWrite(ledPin, HIGH);
  server.send(200, "text/plain", "LED is now ON");
}

void handleOff() {
  digitalWrite(ledPin, LOW);
  server.send(200, "text/plain", "LED is now OFF");
}

void setup() {
  Serial.begin(115200);
  pinMode(ledPin, OUTPUT);
  digitalWrite(ledPin, LOW);

  Serial.println("Connecting to Wi-Fi...");
  WiFi.begin("ArduSimNet", "simulator");
  delay(800);
  Serial.print("IP address: ");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.on("/on", handleOn);
  server.on("/off", handleOff);
  server.begin();
  Serial.println("HTTP server started at http://192.168.1.105/");
}

void loop() {
  tempC = round(map(analogRead(sensorPin), 0, 4095, 15, 35));
  server.handleClient();
  delay(500);
}
